// Cart.razor.cs
using Microsoft.AspNetCore.Components;

namespace MyShop.Components.Pages;

public partial class Cart
{
    [Inject] public ICartService CartService { get; set; } = default!;
    [Inject] public ILogger<Cart> Logger { get; set; } = default!;

    protected override void OnInitialized()
    {
        Logger.LogInformation("Cart has {Count} items", CartService.Items.Count);
    }
}

